WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM payments), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT s.id, s.order_id, s.amount, s.status, s.session_id, (SELECT SUM(t2.quantity) FROM order_items t2 WHERE t2.order_id = s.order_id) AS sum_order_item_quantity FROM sessionized s ORDER BY order_id DESC
